export function FilterChip({
  facet = "{{facet}}",
  value = "{{value}}",
  variant = "{{variant}}",
  accent = "{{accent}}",
}) {
  return (
    <span style={{
      display: "inline-flex", alignItems: "center", gap: 6, fontFamily: "system-ui, sans-serif", fontSize: 14,
      color: "#241430", padding: "6px 8px 6px 12px", borderRadius: 999,
      background: variant === "solid" ? accent : "#FAF7F2",
      border: variant === "outline" ? `1.5px solid ${accent}` : "none",
    }}>
      <span>{facet}: {value}</span>
      <button type="button" aria-label={`Remove filter: ${facet} — ${value}`} style={{
        display: "inline-flex", alignItems: "center", justifyContent: "center", width: 18, height: 18,
        borderRadius: "50%", border: "none", background: "transparent", color: "#241430", cursor: "pointer", padding: 0,
      }}>
        <svg width="10" height="10" viewBox="0 0 10 10" aria-hidden="true"><path d="M1 1L9 9M9 1L1 9" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" /></svg>
      </button>
    </span>
  );
}
